'use strict';

/**
 * Устанавливает поля record.traceId и record.spanId для привязки к трейсингу
 *
 * @returns {Function}
 */
module.exports = () => {
    const { trace, context, isSpanContextValid } = require('@opentelemetry/api');

    const getSpanContext = () => {
        const span = trace.getSpan(context.active());
        if (!span) {
            return undefined;
        }

        const spanContext = span.spanContext();
        if (!isSpanContextValid(spanContext)) {
            return undefined;
        }

        return spanContext;
    };

    /**
     * @param {Object} record
     * @returns {undefined}
     */
    return record => {
        const spanContext = getSpanContext();
        if (!spanContext) {
            return;
        }

        record.spanId = spanContext.spanId || undefined;
        record.traceId = spanContext.traceId || undefined;
    };
};
